#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Returns true iff all entries of `v` are equal.
    /// In particular, if `v.len() <= 1` then the result is true.
    fn mall_equal1(v: &[i32]) -> bool
        ensures
            result
              == forall|i: usize, j: usize|
                   i < v.len() && j < v.len() ==> v[i] == v[j]
    {
        // Trivial case: empty or singleton slice
        if v.len() <= 1 {
            return true;
        }

        let first: i32 = v[0];
        let mut idx: usize = 1;

        while idx < v.len() {
            // idx never exceeds the slice length
            invariant idx <= v.len();
            // all elements in [0, idx) are equal to `first`
            invariant forall|k: usize| k < idx ==> v[k] == first;
            decreases v.len() - idx;

            {
                if v[idx] != first {
                    // we now show ¬(forall i,j. i<len && j<len ==> v[i]==v[j])
                    // by exhibiting (i=0, j=idx) which both are < len but v[0]!=v[idx].
                    assert(0 < v.len());
                    assert(idx < v.len());
                    assert(v[0] == first);
                    assert(v[idx] != first);
                    assert(exists|i: usize, j: usize|
                        i < v.len() && j < v.len() && v[i] != v[j]
                    );
                    return false;
                }
                idx += 1;
            }
        }

        // If we reach here, every element matched `first`, so the
        // universal property holds.
        assert(forall|i: usize, j: usize|
            i < v.len() && j < v.len() ==> v[i] == v[j]
        );
        true
    }

}